#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long total = 1;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            long long term = 1, power = 1;
            while (n % d == 0) {
                n /= d;
                power *= d;
                term += power;
            }
            total *= term;
        }
    }
    if (n > 1) {
        total *= 1 + n;
    }
    cout << total << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        long total = 1;
        for (long d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                long term = 1, power = 1;
                while (n % d == 0) {
                    n /= d;
                    power *= d;
                    term += power;
                }
                total *= term;
            }
        }
        if (n > 1) {
            total *= 1 + n;
        }
        System.out.println(total);
    }
}
